<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, action } from '../api'
const profiles=ref<any[]>([]),models=ref<any[]>([]),base=ref('http://127.0.0.1:11434'),scanning=ref(false),scanError=ref(''),open=ref(false),id=ref(''),busy=ref(false),form=reactive<any>({})
async function load(){profiles.value=await api('/admin/model-profiles')}
onMounted(async()=>{await action(async()=>{await load();const env=await api('/admin/environment');base.value=env.local_model_url});await scan()})
async function scan(){scanning.value=true;scanError.value='';try{models.value=await api('/admin/models/discover?base_url='+encodeURIComponent(base.value))}catch(e){scanError.value=(e as Error).message}scanning.value=false}
function edit(p?:any,copy=false){id.value=copy?'':p?.id||'';Object.assign(form,p?{name:p.name+(copy?' · 副本':''),purpose:p.purpose,provider:p.provider,model:p.model,base_url:p.base_url,dimension:p.dimension,temperature:p.temperature,api_key:''}:{name:'',purpose:'generation',provider:'openai',model:'',base_url:'',dimension:1024,temperature:.1,api_key:''});open.value=true}
function addLocal(m:any){edit();Object.assign(form,{name:m.name,purpose:m.embedding?'embedding':'generation',provider:'ollama',model:m.name,base_url:base.value,dimension:m.dimension||1024})}
async function save(){busy.value=true;await action(async()=>{const body={...form,dimension:form.purpose==='embedding'?form.dimension:null};if(id.value&&!body.api_key)delete body.api_key;await api('/admin/model-profiles'+(id.value?'/'+id.value:''),id.value?'PUT':'POST',body);open.value=false;await load();ElMessage.success('模型配置已保存')});busy.value=false}
async function test(p:any){busy.value=true;await action(async()=>{const r=await api('/admin/model-profiles/'+p.id+'/test','POST');ElMessage.success(r.message)});busy.value=false}
</script>
<template><section class="page"><div class="page-eyebrow">ADMINISTRATION / MODELS</div><div class="page-title"><div><h1>模型与连接</h1><p class="muted">生成模型负责理解与表达，Embedding 模型负责知识检索。</p></div><el-button type="primary" @click="edit()">＋ 添加模型配置</el-button></div><section class="panel discovery"><div class="section-heading"><div><h3>发现本地模型</h3><p class="muted">扫描指定 Ollama 服务中的已安装模型，不会下载新模型。</p></div><el-tag type="success" effect="plain">LOCAL DISCOVERY</el-tag></div><div class="inline-form"><el-input v-model="base" placeholder="http://host.containers.internal:11434"/><el-button :loading="scanning" @click="scan">扫描模型</el-button></div><el-alert v-if="scanError" :title="scanError" type="info" :closable="false" class="spaced"/><div class="discovered-models"><div v-for="m in models" :key="m.name" class="discovered-model"><span class="model-dot"></span><div><b>{{m.name}}</b><p>{{m.embedding?'Embedding · '+m.dimension+' 维':'生成模型'}}</p></div><el-button size="small" @click="addLocal(m)">添加配置</el-button></div></div></section><h2 class="spaced">已保存配置 <span class="muted small">{{profiles.length}}</span></h2><el-table :data="profiles" class="panel"><el-table-column label="名称" min-width="170"><template #default="{row}"><b>{{row.name}}</b><div class="muted small">{{row.model}}</div></template></el-table-column><el-table-column label="用途" width="140"><template #default="{row}"><el-tag :type="row.purpose==='embedding'?'warning':'success'">{{row.purpose==='embedding'?'Embedding':'生成模型'}}</el-tag></template></el-table-column><el-table-column prop="provider" label="提供方" width="110"/><el-table-column label="维度 / 密钥" width="130"><template #default="{row}">{{row.dimension||'—'}} / {{row.has_api_key?'已保存':'无'}}</template></el-table-column><el-table-column label="操作" min-width="240"><template #default="{row}"><el-button size="small" :loading="busy" @click="test(row)">测试</el-button><el-button size="small" @click="edit(row)">编辑</el-button><el-button size="small" @click="edit(row,true)">复制</el-button><el-button size="small" @click="action(async()=>{await api('/admin/model-profiles/'+row.id,'DELETE');await load()})">删除</el-button></template></el-table-column></el-table><p class="form-help">已发布应用使用的配置变更模型时，请复制配置，然后到应用中选择并发布。密钥仅在服务端加密保存。</p><el-drawer v-model="open" :title="id?'编辑模型':'添加模型'" size="min(560px, 96vw)"><el-form label-position="top"><el-form-item label="配置名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="用途"><el-radio-group v-model="form.purpose"><el-radio-button value="generation">生成模型</el-radio-button><el-radio-button value="embedding">Embedding</el-radio-button></el-radio-group></el-form-item><el-form-item label="提供方"><el-select v-model="form.provider" class="full-width"><el-option label="云端 · OpenAI 兼容接口" value="openai"/><el-option label="本地 · Ollama" value="ollama"/><el-option v-if="form.provider==='demo'" label="演示模式" value="demo"/></el-select></el-form-item><el-form-item label="服务地址"><el-input v-model="form.base_url" :placeholder="form.provider==='ollama'?'http://host.containers.internal:11434':'https://服务地址/v1'"/></el-form-item><el-form-item label="模型名称"><el-input v-model="form.model" placeholder="填写服务提供的模型 ID"/></el-form-item><el-form-item v-if="form.purpose==='embedding'" label="输出向量维度"><el-input-number v-model="form.dimension" :min="1" :max="8192"/></el-form-item><el-form-item v-else label="Temperature"><el-input-number v-model="form.temperature" :step=".1" :min="0" :max="2"/></el-form-item><el-form-item v-if="form.provider==='openai'" label="API 密钥"><el-input v-model="form.api_key" type="password" show-password placeholder="编辑时留空保留原密钥" autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存配置</el-button></template></el-drawer></section></template>
